import{_ as a,C as s,o,c as r,j as t,a as i,E as h,a6 as l}from"./chunks/framework.CCKCzdWs.js";const w=JSON.parse('{"title":"Run on my machine","description":"Ask the desktop app on your own machine to run Playwright tests from the dashboard: who may ask, how an administrator turns it on, Connected apps, and why a requested run is yours alone.","frontmatter":{"title":"Run on my machine","description":"Ask the desktop app on your own machine to run Playwright tests from the dashboard: who may ask, how an administrator turns it on, Connected apps, and why a requested run is yours alone.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/run-on-my-machine.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/run-on-my-machine.html"}],["meta",{"property":"og:title","content":"Run on my machine | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Ask the desktop app on your own machine to run Playwright tests from the dashboard: who may ask, how an administrator turns it on, Connected apps, and why a requested run is yours alone."}]]},"headers":[],"relativePath":"features/run-on-my-machine.md","filePath":"features/run-on-my-machine.md","lastUpdated":1794082259000}'),d={name:"features/run-on-my-machine.md"};function c(p,e,u,m,y,f){const n=s("Needs");return o(),r("div",null,[e[0]||(e[0]=t("h1",{id:"run-on-my-machine",tabindex:"-1"},[i("Run on my machine "),t("a",{class:"header-anchor",href:"#run-on-my-machine","aria-label":'Permalink to "Run on my machine"'},"​")],-1)),h(n,{desktop:"",admin:""}),e[1]||(e[1]=l('<p>Run on my machine lets a signed-in person ask the desktop app on their own machine to run tests they found on the dashboard. The instance carries the request; the app asks them before every run, in its own window, and runs the tests in their own folder. The run it starts reports back to the instance as a <strong>requested run</strong>: theirs alone, and kept out of everything the team sees.</p><h2 id="experimental" tabindex="-1">Experimental <a class="header-anchor" href="#experimental" aria-label="Permalink to &quot;Experimental&quot;">​</a></h2><p><strong>Experimental.</strong> Run on my machine is off by default. The instance&#39;s side ships: turning it on, the requests and their rules, the connection a desktop app holds, Connected apps, and the privacy of a requested run. The desktop app does not take requests in this release, so nothing asks for a run from a page yet. The design is in the <a href="https://github.com/PiwiTests/piwi/blob/main/proposals/run-on-my-machine.md" target="_blank" rel="noreferrer">Run on my machine design record</a>.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>An administrator turns it on in <strong>Settings → Capabilities → Off until turned on → Run on my machine → Turn on</strong>, and off the same way. It needs <a href="/operate/authentication.html">sign-in</a> turned on: a request belongs to the person who made it, so an instance without accounts refuses it. A project admin declines it for one project in <strong>Project → Settings → Capabilities</strong>, which lists it while the instance has it on.</p><p>Turned off or declined, the instance refuses every request for that project, and a connected app receives none.</p><h2 id="who-may-ask" tabindex="-1">Who may ask <a class="header-anchor" href="#who-may-ask" aria-label="Permalink to &quot;Who may ask&quot;">​</a></h2><ul><li><strong>Contributors and up</strong> may ask (<code>run:request</code>), on the projects where they hold the role. A Contributor cannot submit a run with an API key; a requested run does not need to, since its app reports it with a credential that starts that one run.</li><li><strong>Only a signed-in session</strong> creates a request: never an API key, a CI job or an MCP client.</li><li><strong>A request goes only to the person&#39;s own apps</strong>, which take it only on projects where they may run tests.</li></ul><h2 id="connected-apps" tabindex="-1">Connected apps <a class="header-anchor" href="#connected-apps" aria-label="Permalink to &quot;Connected apps&quot;">​</a></h2><p><strong>Settings → Account → Connected apps</strong> lists the apps you connected from their own window: Piwi Picker, an editor, the desktop app, Piwi Runner. Each shows when it connected and, for an app that runs tests, <strong>Online now</strong> while it holds its connection to the instance open and has called the instance within the last two minutes, or else when it was last seen. <strong>Revoke</strong> disconnects one: the instance closes the connection of an app that runs tests at once, and refuses its next call. An administrator sees the same list for any user in <strong>Settings → Users → API keys</strong>. The keys these apps hold are not listed under API keys.</p><p>The instance sends a connected app each request as it is made, on that connection, with the time it stops waiting, and the requests still waiting each time the app connects again. When a waiting request is stopped, or another of your apps takes it, the instance tells the others to drop it. An app can also ask for its requests instead, where a proxy cuts long connections.</p><h2 id="a-requested-run-is-yours-alone" tabindex="-1">A requested run is yours alone <a class="header-anchor" href="#a-requested-run-is-yours-alone" aria-label="Permalink to &quot;A requested run is yours alone&quot;">​</a></h2><p>A requested run shows to the person who asked for it, and to nobody else:</p><ul><li><strong>Its own page</strong> opens for you, and reads as not found for anyone else, as its executions, its attachments, its traces and its reports do.</li><li><strong>The test&#39;s recent executions</strong> list it for you, marked <strong>On your machine</strong>. The test&#39;s pass rate, flaky score and history leave it out.</li><li><strong>No list a project&#39;s members read</strong> shows it: the project&#39;s runs, search, analytics, the MCP tools.</li><li><strong>With sign-in turned off, or once its requester is deleted</strong>, nobody sees it.</li></ul><p>It was run to look, on a branch and a machine the team did not choose, so it stays out of everything the team sees: no failure clusters, flakiness, analytics or baselines; no notifications, pull-request comments or tracker writes; no coverage, and it never sets the project&#39;s default branch. It is never kept forever: retention removes it, and you can delete it yourself from its page. Someone who holds <code>run:delete</code> on the project can delete it through the API without seeing it.</p><p>A <a href="./share-links.html">share link</a> you make for one of its executions opens for whoever has the link, as any share link does, so you can show a teammate what happened on your machine. It appears in the project&#39;s list of share links.</p><h2 id="one-instance-one-replica" tabindex="-1">One instance, one replica <a class="header-anchor" href="#one-instance-one-replica" aria-label="Permalink to &quot;One instance, one replica&quot;">​</a></h2><p>Whether an app is online is held in the server&#39;s memory, as live run updates are. The instance runs as one replica, as the <a href="/operate/deployment.html">deployment page</a> requires.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./desktop.html">Desktop app</a>: the app that takes requests</li><li><a href="./desktop-runs.html">Desktop app runs</a>: the runs the desktop app starts and how you follow them</li><li><a href="./share-links.html">Share links</a>: showing one execution to someone without an account</li></ul>',20))])}const k=a(d,[["render",c]]);export{w as __pageData,k as default};
